const project = $json.project_name || 'PDF to PPT Project';
const target = Number($json.target_slide_count || 10);
const binaryKeys = Object.keys($binary || {});
if (!binaryKeys.length) throw new Error('No PDF file uploaded');
const key = binaryKeys.includes('pdf_file') ? 'pdf_file' : binaryKeys[0];
const fileName = $binary[key].fileName || 'uploaded.pdf';
if (!fileName.toLowerCase().endsWith('.pdf')) throw new Error('Uploaded file must be PDF');
const runId = 'pdf_to_ppt_' + new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14);
return [{ json: { run_id: runId, project_name: project, target_slide_count: target, binary_key: key, original_file_name: fileName }, binary: $binary }];

const fs = require('fs');
const path = require('path');
const runId = $json.run_id;
const key = $json.binary_key;
const dir = `/tmp/pdf_to_ppt/${runId}`;
fs.mkdirSync(dir, { recursive: true });
const inputPath = path.join(dir, 'input.pdf');
const buf = await this.helpers.getBinaryDataBuffer(0, key);
fs.writeFileSync(inputPath, buf);
return [{ json: { ...$json, local_pdf_path: inputPath, local_run_dir: dir }, binary: $binary }];

const output = $json.stdout || $json.data || '';
let parsed;
try { parsed = JSON.parse(output); } catch (e) { throw new Error('Backend did not return valid JSON: ' + output.slice(0,500)); }
if (!parsed.success) throw new Error('Backend pipeline failed');
return [{ json: parsed }];

const fs = require('fs');
const pptxPath = $json.final_pptx;
if (!fs.existsSync(pptxPath)) throw new Error('Final PPTX not found: ' + pptxPath);
const data = fs.readFileSync(pptxPath);
return [{ json: $json, binary: { final_pptx: await this.helpers.prepareBinaryData(data, `${$json.run_id}_${($json.project_name || 'presentation').replace(/[^a-z0-9_-]+/gi,'_')}.pptx`, 'application/vnd.openxmlformats-officedocument.presentationml.presentation') } }];
